def tao_khach_hang(apps, schema_editor):
    """Hồ sơ khách hàng cho các số đã gửi trước đây (trạng thái Đã gửi nếu gửi thành công).
    Số gửi trước bản này chưa có Zalo ID nên chưa theo dõi được đồng ý kết bạn / trả lời."""
    LichSuGui = apps.get_model("guitin", "LichSuGui")
    KhachHang = apps.get_model("guitin", "KhachHang")
    khach = {}
    for h in LichSuGui.objects.order_by("thoi_gian").values("sdt", "ten_zalo", "nguoi_gui_id", "thoi_gian", "ket_ban", "tin_nhan"):
        k = khach.setdefault(h["sdt"], {"sdt": h["sdt"], "gui_dau_luc": h["thoi_gian"], "trang_thai": "moi"})
        k["ten_zalo"] = h["ten_zalo"] or k.get("ten_zalo", "")
        k["nhan_vien_id"] = h["nguoi_gui_id"] or k.get("nhan_vien_id")
        if h["tin_nhan"] == "Đã gửi" or (h["tin_nhan"] == "-" and h["ket_ban"] == "Đã gửi"):
            k["trang_thai"] = "da_gui"
    KhachHang.objects.bulk_create([KhachHang(**k) for k in khach.values()], batch_size=500, ignore_conflicts=True)


